/**
 * Tests for the opt-in session category shadow provider.
 *
 * HTTP is always a mocked fetch; no test reaches the network.
 *
 * Validates:
 * - contract: the Choice criteria set is exactly WORK_CATEGORIES, in order,
 *   with the same descriptions the haiku prompt uses
 * - the haiku prompt sentence is byte-identical to the pre-shadow text
 * - opt-in gating (provider value AND key both required)
 * - request shape: endpoint, bearer header, pinned model, excerpt cap
 * - answer parsing and every fail-open path (non-2xx, malformed, throw, timeout)
 * - the shadow pair record: written once, labels only, no prompt text
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import * as fs from 'node:fs';
import * as path from 'node:path';
import * as os from 'node:os';
import {
  CATEGORY_DESCRIPTIONS,
  WORK_CATEGORIES,
  buildGeneratorPrompt,
  parseIdentityCategory,
} from '../../lib/session-identity.js';
import {
  CATEGORY_PROVIDER_ENV,
  JEV_ENDPOINT,
  JEV_MODEL,
  JEV_QUESTION_ID,
  TYPESAFE_KEY_ENV,
  buildJevCategoryRequest,
  classifyCategoryWithJev,
  isJevShadowEnabled,
  parseJevCategoryAnswer,
  recordCategoryShadow,
  resolveCategoryProvider,
  startJevCategoryShadow,
} from '../../lib/session-category-provider.js';

const KEY = 'test-key-not-real';

function answerBody(choice: string, extra: Record<string, unknown> = {}) {
  return {
    model: JEV_MODEL,
    answers: {
      [JEV_QUESTION_ID]: {
        type: 'choice',
        choice,
        confidence: 0.82,
        probabilities: { bugfix: 0.85, feature: 0.1, docs: 0.05, bogus: 0.3 },
        ...extra,
      },
    },
    usage: { input_tokens: 312, output_tokens: 0 },
  };
}

function mockFetch(status: number, body: unknown, headers: Record<string, string> = {}) {
  return vi.fn(async () =>
    new Response(JSON.stringify(body), {
      status,
      headers: { 'content-type': 'application/json', ...headers },
    }),
  ) as unknown as typeof fetch;
}

describe('category set contract', () => {
  it('the Choice criteria keys are exactly WORK_CATEGORIES, in order', () => {
    const req = buildJevCategoryRequest('fix the login bug', 'fix/login');
    const criteria = req.questions[JEV_QUESTION_ID].criteria;
    expect(Object.keys(criteria)).toEqual([...WORK_CATEGORIES]);
  });

  it('the Choice descriptions are the same descriptions the haiku prompt uses', () => {
    const req = buildJevCategoryRequest('x', '');
    const prompt = buildGeneratorPrompt('x', '');
    for (const c of WORK_CATEGORIES) {
      expect(req.questions[JEV_QUESTION_ID].criteria[c]).toBe(CATEGORY_DESCRIPTIONS[c]);
      expect(prompt).toContain(`${c} (${CATEGORY_DESCRIPTIONS[c]})`);
    }
    expect(Object.keys(CATEGORY_DESCRIPTIONS)).toEqual([...WORK_CATEGORIES]);
  });

  it('adds no extra option (no "other"), so the two label spaces are identical', () => {
    const req = buildJevCategoryRequest('x', '');
    expect(Object.keys(req.questions[JEV_QUESTION_ID].criteria)).toHaveLength(WORK_CATEGORIES.length);
  });

  it('keeps the haiku category sentence byte-identical to the pre-shadow prompt', () => {
    expect(buildGeneratorPrompt('x', '')).toContain(
      'Choose the SINGLE category that best fits the work: bugfix (fixing a bug or incident), feature (new capability), docs (documentation or research), refactor (restructuring with no behavior change), infra (CI, build, deploy, tooling), perf (performance), design (UI, UX, visual), testing (tests or QA).',
    );
  });
});

describe('parseIdentityCategory', () => {
  it('reads the haiku category from raw stdout, tolerating prose around the JSON', () => {
    expect(parseIdentityCategory('Here: {"title":"Fix it","category":" BugFix ","emoji":"x"} done')).toBe('bugfix');
  });

  it('returns undefined for an out-of-set category, a color-only object, or junk', () => {
    expect(parseIdentityCategory('{"title":"t","category":"other"}')).toBeUndefined();
    expect(parseIdentityCategory('{"title":"t","color":"red"}')).toBeUndefined();
    expect(parseIdentityCategory('I cannot help with that.')).toBeUndefined();
    expect(parseIdentityCategory('{not json}')).toBeUndefined();
  });
});

describe('opt-in gating', () => {
  it('defaults to haiku when the provider variable is unset or anything else', () => {
    expect(resolveCategoryProvider({})).toBe('haiku');
    expect(resolveCategoryProvider({ [CATEGORY_PROVIDER_ENV]: 'haiku' })).toBe('haiku');
    expect(resolveCategoryProvider({ [CATEGORY_PROVIDER_ENV]: 'openai' })).toBe('haiku');
    expect(resolveCategoryProvider({ [CATEGORY_PROVIDER_ENV]: ' JEV ' })).toBe('jev');
  });

  it('needs BOTH the provider and a non-empty key', () => {
    expect(isJevShadowEnabled({ [CATEGORY_PROVIDER_ENV]: 'jev' })).toBe(false);
    expect(isJevShadowEnabled({ [CATEGORY_PROVIDER_ENV]: 'jev', [TYPESAFE_KEY_ENV]: '  ' })).toBe(false);
    expect(isJevShadowEnabled({ [TYPESAFE_KEY_ENV]: KEY })).toBe(false);
    expect(isJevShadowEnabled({ [CATEGORY_PROVIDER_ENV]: 'jev', [TYPESAFE_KEY_ENV]: KEY })).toBe(true);
  });

  it('startJevCategoryShadow makes no call when disabled', () => {
    const fetchImpl = mockFetch(200, answerBody('bugfix'));
    expect(startJevCategoryShadow('p', 'b', '/nonexistent/x.json', {}, fetchImpl)).toBeNull();
    expect(fetchImpl).not.toHaveBeenCalled();
  });
});

describe('buildJevCategoryRequest', () => {
  it('pins the model and caps the prompt excerpt at 600 chars with whitespace collapsed', () => {
    const req = buildJevCategoryRequest(`fix   the\n\nbug ${'a'.repeat(900)}`, 'fix/x');
    expect(req.model).toBe(JEV_MODEL);
    expect(req.model).not.toMatch(/latest|preview/);
    expect(req.state.git_branch).toBe('fix/x');
    expect(req.state.first_prompt.startsWith('fix the bug ')).toBe(true);
    expect(req.state.first_prompt.length).toBe(600);
    expect(req.questions[JEV_QUESTION_ID].type).toBe('choice');
  });
});

describe('parseJevCategoryAnswer', () => {
  it('parses choice, confidence, in-set probabilities and input tokens', () => {
    const parsed = parseJevCategoryAnswer(answerBody('bugfix'));
    expect(parsed).toEqual({
      category: 'bugfix',
      confidence: 0.82,
      probabilities: { bugfix: 0.85, feature: 0.1, docs: 0.05 },
      inputTokens: 312,
    });
  });

  it('rejects a choice outside the closed set and malformed bodies', () => {
    expect(parseJevCategoryAnswer(answerBody('other'))).toBeNull();
    expect(parseJevCategoryAnswer(null)).toBeNull();
    expect(parseJevCategoryAnswer({ answers: {} })).toBeNull();
    expect(parseJevCategoryAnswer({ answers: { [JEV_QUESTION_ID]: 'bugfix' } })).toBeNull();
  });
});

describe('classifyCategoryWithJev (mocked HTTP)', () => {
  it('POSTs the Choice with a bearer key and returns the typed answer', async () => {
    const fetchImpl = mockFetch(200, answerBody('bugfix'), { 'x-typesafe-request-id': 'req_1' });
    let t = 1000;
    const result = await classifyCategoryWithJev({
      firstPrompt: 'the login page 404s after sign in',
      branch: 'fix/login',
      apiKey: KEY,
      fetchImpl,
      now: () => (t += 120),
    });
    expect(result).toMatchObject({
      ok: true,
      category: 'bugfix',
      confidence: 0.82,
      inputTokens: 312,
      requestId: 'req_1',
      latencyMs: 120,
    });
    const [url, init] = vi.mocked(fetchImpl).mock.calls[0] as [string, RequestInit];
    expect(url).toBe(JEV_ENDPOINT);
    expect(init.method).toBe('POST');
    expect((init.headers as Record<string, string>).Authorization).toBe(`Bearer ${KEY}`);
    const sent = JSON.parse(String(init.body));
    expect(Object.keys(sent.questions[JEV_QUESTION_ID].criteria)).toEqual([...WORK_CATEGORIES]);
  });

  it('fails open on a non-2xx status', async () => {
    const result = await classifyCategoryWithJev({
      firstPrompt: 'p',
      branch: '',
      apiKey: KEY,
      fetchImpl: mockFetch(429, { error: 'rate limited' }),
    });
    expect(result).toMatchObject({ ok: false, error: 'http 429', status: 429 });
  });

  it('fails open on a malformed answer', async () => {
    const result = await classifyCategoryWithJev({
      firstPrompt: 'p',
      branch: '',
      apiKey: KEY,
      fetchImpl: mockFetch(200, { answers: {} }),
    });
    expect(result).toMatchObject({ ok: false, error: 'malformed answer' });
  });

  it('fails open when fetch throws, without echoing the key', async () => {
    const fetchImpl = vi.fn(async () => {
      throw new TypeError(`network down ${KEY}`);
    }) as unknown as typeof fetch;
    const result = await classifyCategoryWithJev({ firstPrompt: 'p', branch: '', apiKey: KEY, fetchImpl });
    expect(result).toMatchObject({ ok: false, error: 'TypeError', status: null });
    expect(JSON.stringify(result)).not.toContain(KEY);
  });

  it('aborts at the timeout and reports it as a timeout', async () => {
    const fetchImpl = vi.fn(
      (_url: string, init: RequestInit) =>
        new Promise<Response>((_resolve, reject) => {
          init.signal?.addEventListener('abort', () => reject(new DOMException('aborted', 'AbortError')));
        }),
    ) as unknown as typeof fetch;
    const result = await classifyCategoryWithJev({
      firstPrompt: 'p',
      branch: '',
      apiKey: KEY,
      fetchImpl,
      timeoutMs: 20,
    });
    expect(result).toMatchObject({ ok: false, error: 'timeout' });
  });
});

describe('shadow files', () => {
  let tmpDir: string;
  let jevPath: string;
  let shadowPath: string;

  beforeEach(() => {
    tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'category-shadow-'));
    jevPath = path.join(tmpDir, 'session-identity.jev.json');
    shadowPath = path.join(tmpDir, 'session-identity.shadow.json');
  });

  afterEach(() => {
    fs.rmSync(tmpDir, { recursive: true, force: true });
  });

  it('startJevCategoryShadow writes the result without the key or the prompt', async () => {
    const env = { [CATEGORY_PROVIDER_ENV]: 'jev', [TYPESAFE_KEY_ENV]: KEY };
    const secretPrompt = 'private prompt text that must not be stored';
    await startJevCategoryShadow(secretPrompt, 'feat/x', jevPath, env, mockFetch(200, answerBody('feature')));
    const written = fs.readFileSync(jevPath, 'utf8');
    expect(JSON.parse(written)).toMatchObject({ ok: true, category: 'feature', model: JEV_MODEL });
    expect(written).not.toContain(KEY);
    expect(written).not.toContain(secretPrompt);
  });

  it('records the pair once haiku settles, and only once', () => {
    fs.writeFileSync(
      jevPath,
      JSON.stringify({ ok: true, model: JEV_MODEL, category: 'docs', confidence: 0.9, latencyMs: 210, inputTokens: 400 }),
    );
    expect(recordCategoryShadow(jevPath, shadowPath, null, false)).toBeNull();
    const record = recordCategoryShadow(jevPath, shadowPath, 'infra', true);
    expect(record).toMatchObject({
      provider: 'jev',
      haiku: 'infra',
      jev: 'docs',
      agree: false,
      jev_confidence: 0.9,
      latency_ms: 210,
      input_tokens: 400,
      error: null,
    });
    expect(recordCategoryShadow(jevPath, shadowPath, 'infra', true)).toBeNull();
  });

  it('records a failed Jev call with its error and agree=null', () => {
    fs.writeFileSync(jevPath, JSON.stringify({ ok: false, error: 'timeout', status: null, latencyMs: 1500 }));
    expect(recordCategoryShadow(jevPath, shadowPath, 'bugfix', true)).toMatchObject({
      haiku: 'bugfix',
      jev: null,
      agree: null,
      error: 'timeout',
    });
  });

  it('does nothing while the Jev result has not landed', () => {
    expect(recordCategoryShadow(jevPath, shadowPath, 'bugfix', true)).toBeNull();
    expect(fs.existsSync(shadowPath)).toBe(false);
  });
});
